mapper.select:
SELECT d.id AS detailId, t.id AS taskId, d.log_type AS logType, d.log_time AS logTime,
       d.content AS content, t.app_version AS appVersion, t.build_version AS buildVersion,
       'native' AS channel
FROM logan_log_detail d
JOIN logan_task t ON t.id = d.task_id
WHERE t.device_id = #{deviceId}
  AND t.app_id = #{appId}
  AND d.log_time BETWEEN #{beginTime} AND #{endTime}
  AND d.log_type < 90
ORDER BY d.log_time ASC
LIMIT 0,#{limit}

SELECT wd.id AS detailId, wt.id AS taskId, wd.log_type AS logType, wd.log_time AS logTime,
       wd.content AS content, '' AS appVersion, '' AS buildVersion, 'h5' AS channel
FROM web_detail wd
JOIN web_task wt ON wt.id = wd.task_id
WHERE wt.device_id = #{deviceId}
  AND wt.app_id = #{appId}
  AND wd.log_time BETWEEN #{beginTime} AND #{endTime}
ORDER BY wd.log_time ASC
LIMIT 0,#{limit}

SELECT device_id AS deviceId, kind, fingerprint,
       FROM_UNIXTIME(crash_time / 1000, '%Y-%m-%d') AS crashDate,
       COUNT(*) AS cnt
FROM logan_crash

  AND app_id = #{appId}
  AND crash_time >= #{beginTime}
  AND crash_time <= #{endTime}

GROUP BY device_id, kind, fingerprint, crashDate
ORDER BY crashDate DESC
LIMIT 0,500
